PATH = Path("/config/custom_components/markvarec_camera_push_sync/__init__.py")
EXPECTED_SHA = "467df4e40262f99d1dd89506c0c37275f732c5acbcc5091264842818c794f3b5"

original = PATH.read_text(encoding="utf-8")
actual_sha = hashlib.sha256(PATH.read_bytes()).hexdigest()
assert actual_sha == EXPECTED_SHA, f"unexpected source sha: {actual_sha}"

text = original

old = '"""Keep vendor camera app notifications aligned with Markvarec security."""'
new = '"""Keep vendor camera notifications and active deterrence aligned with Markvarec security."""'
assert text.count(old) == 1
text = text.replace(old, new, 1)

old = 'EZVIZ_ENTITY = "camera.dvur"\nEZVIZ_DIAG = "binary_sensor.markvarec_ezviz_app_push"\nIMOU_DIAG = "binary_sensor.markvarec_imou_app_push"\nEZVIZ_DOMAIN = "ezviz"\nIMOU_DOMAIN = "imou_life"\n'
new = 'EZVIZ_ENTITY = "camera.dvur"\nIMOU_ENTITY = "camera.branka_live"\nEZVIZ_DIAG = "binary_sensor.markvarec_ezviz_app_push"\nIMOU_DIAG = "binary_sensor.markvarec_imou_app_push"\nIMOU_DETERRENCE_DIAG = "binary_sensor.markvarec_imou_odstraseni"\nEZVIZ_DOMAIN = "ezviz"\nIMOU_DOMAIN = "imou_life"\n'
assert text.count(old) == 1
text = text.replace(old, new, 1)

anchor = '\ndef _ezviz_cloud_push(coordinator: Any, serial: str) -> bool | None:\n'
assert text.count(anchor) == 1
helpers = 'def _imou_address(hass: HomeAssistant) -> tuple[str, str, str | None] | None:\n    """Resolve the Imou device/channel from the live HA entity registry."""\n    ent = er.async_get(hass).async_get(IMOU_ENTITY)\n    if ent is None or ent.device_id is None:\n        return None\n    dev = dr.async_get(hass).async_get(ent.device_id)\n    if dev is None:\n        return None\n    for domain, identifier in dev.identifiers:\n        if domain != IMOU_DOMAIN:\n            continue\n        raw = str(identifier)\n        if "_" not in raw:\n            return raw, "0", getattr(ent, "config_entry_id", None)\n        device_id, channel_id = raw.rsplit("_", 1)\n        if device_id and channel_id:\n            return device_id, channel_id, getattr(ent, "config_entry_id", None)\n    return None\n\n\ndef _set_deterrence_diag(\n    hass: HomeAssistant,\n    state: str,\n    *,\n    desired: bool,\n    security_state: str,\n    reason: str,\n    sync_reason: str,\n    **attrs: Any,\n) -> None:\n    data = {\n        "friendly_name": "Imou Branka - aktivni odstraseni",\n        "desired_deterrence": desired,\n        "security_entity": SECURITY_ENTITY,\n        "security_state": security_state,\n        "policy_reason": reason,\n        "fail_safe": security_state not in ("on", "off"),\n        "sync_reason": sync_reason,\n    }\n    data.update(attrs)\n    hass.states.async_set(IMOU_DETERRENCE_DIAG, state, data)\n\n\nasync def _imou_get_capability_switch(\n    client: Any,\n    device_id: str,\n    channel_id: str | None,\n    enable_type: str,\n) -> bool:\n    params: dict[str, Any] = {\n        "deviceId": device_id,\n        "enableType": enable_type,\n    }\n    if channel_id is not None:\n        params["channelId"] = channel_id\n    result = await client.async_request_api("/openapi/getDeviceCameraStatus", params)\n    status = result.get("status")\n    if status == "on":\n        return True\n    if status == "off":\n        return False\n    raise ValueError(f"{enable_type} returned unexpected status: {status!r}")\n\n\nasync def _imou_set_capability_switch(\n    client: Any,\n    device_id: str,\n    channel_id: str | None,\n    enable_type: str,\n    enabled: bool,\n) -> None:\n    params: dict[str, Any] = {\n        "deviceId": device_id,\n        "enableType": enable_type,\n        "enable": enabled,\n    }\n    if channel_id is not None:\n        params["channelId"] = channel_id\n    await client.async_request_api("/openapi/setDeviceCameraStatus", params)\n\n\nasync def _imou_read_linkage_siren(\n    client: Any,\n    device_id: str,\n    channel_id: str,\n) -> tuple[bool, str | None]:\n    """Read linkageSiren; the capability supports channel or device scope."""\n    try:\n        return (\n            await _imou_get_capability_switch(\n                client, device_id, channel_id, "linkageSiren"\n            ),\n            channel_id,\n        )\n    except Exception as channel_err:\n        try:\n            return (\n                await _imou_get_capability_switch(\n                    client, device_id, None, "linkageSiren"\n                ),\n                None,\n            )\n        except Exception as device_err:\n            raise RuntimeError(\n                "linkageSiren read failed for both channel and device scope: "\n                f"{type(channel_err).__name__}/{type(device_err).__name__}"\n            ) from device_err\n\n\n'
text = text.replace(anchor, "\n" + helpers + anchor, 1)

start = text.index("async def _sync_imou(")
end = text.index("\n\nasync def async_setup", start)
new_sync = 'async def _sync_imou(\n    hass: HomeAssistant,\n    runtime: dict[str, Any],\n    desired: bool,\n    security_state: str,\n    policy_reason: str,\n    sync_reason: str,\n    *,\n    force: bool,\n) -> None:\n    # Keep the official HTTPS callback alive, switch only vendor-phone push\n    # delivery, and independently align the camera\'s own alarm-linked\n    # deterrence. Detection/recording remain untouched.\n    from custom_components.imou_life.const import (\n        PARAM_ENABLE_EVENT_PUSH,\n        PARAM_EVENT_PUSH_TYPES,\n        PARAM_WEBHOOK_ID,\n        PARAM_WEBHOOK_URL,\n        event_push_types_to_callback_flags,\n    )\n\n    address = _imou_address(hass)\n    if address is None:\n        _set_diag(\n            hass,\n            IMOU_DIAG,\n            "unavailable",\n            desired=desired,\n            security_state=security_state,\n            reason=policy_reason,\n            provider="Imou",\n            sync_reason=sync_reason,\n            error="camera.branka_live address not found",\n        )\n        _set_deterrence_diag(\n            hass,\n            "unavailable",\n            desired=desired,\n            security_state=security_state,\n            reason=policy_reason,\n            sync_reason=sync_reason,\n            error="camera.branka_live address not found",\n        )\n        return\n\n    device_id, channel_id, target_entry_id = address\n    attempted = 0\n    callback_successes = 0\n    deterrence_successes = 0\n    callback_errors: list[str] = []\n    deterrence_errors: list[str] = []\n    callback_wrote = False\n    deterrence_wrote = False\n    white_light_readback: bool | None = None\n    siren_readback: bool | None = None\n    siren_scope: str | None = None\n\n    for entry in hass.config_entries.async_entries(IMOU_DOMAIN):\n        if target_entry_id and entry.entry_id != target_entry_id:\n            continue\n        runtime_data = getattr(entry, "runtime_data", None)\n        client = getattr(runtime_data, "client", None)\n        if client is None:\n            callback_errors.append(f"{entry.entry_id}:runtime_not_ready")\n            deterrence_errors.append(f"{entry.entry_id}:runtime_not_ready")\n            continue\n\n        attempted += 1\n\n        if bool(entry.options.get(PARAM_ENABLE_EVENT_PUSH)):\n            webhook_id = entry.data.get(PARAM_WEBHOOK_ID, "")\n            if not webhook_id:\n                callback_errors.append(f"{entry.entry_id}:missing_webhook_id")\n            elif force or runtime.get("imou_last_desired") is not desired:\n                try:\n                    callback_url = (\n                        entry.options.get(PARAM_WEBHOOK_URL)\n                        or webhook.async_generate_url(hass, webhook_id)\n                    )\n                    raw_types = entry.options.get(PARAM_EVENT_PUSH_TYPES, [])\n                    callback_flags = event_push_types_to_callback_flags(\n                        list(raw_types)\n                    )\n                    await client.async_set_message_callback(\n                        status="on",\n                        callback_url=callback_url,\n                        callback_flag=callback_flags if callback_flags else None,\n                        base_push="1" if desired else "2",\n                    )\n                    callback_successes += 1\n                    callback_wrote = True\n                except Exception as err:\n                    callback_errors.append(\n                        f"{entry.entry_id}:{type(err).__name__}"\n                    )\n                    _LOGGER.exception(\n                        "Failed to sync Imou app notification policy for entry %s",\n                        entry.entry_id,\n                    )\n            else:\n                callback_successes += 1\n        else:\n            callback_errors.append(f"{entry.entry_id}:event_push_disabled")\n\n        try:\n            white_light_readback = await _imou_get_capability_switch(\n                client,\n                device_id,\n                channel_id,\n                "linkageWhiteLight",\n            )\n            siren_readback, siren_scope = await _imou_read_linkage_siren(\n                client,\n                device_id,\n                channel_id,\n            )\n\n            if white_light_readback != desired:\n                await _imou_set_capability_switch(\n                    client,\n                    device_id,\n                    channel_id,\n                    "linkageWhiteLight",\n                    desired,\n                )\n                deterrence_wrote = True\n\n            if siren_readback != desired:\n                await _imou_set_capability_switch(\n                    client,\n                    device_id,\n                    siren_scope,\n                    "linkageSiren",\n                    desired,\n                )\n                deterrence_wrote = True\n\n            if deterrence_wrote:\n                await asyncio.sleep(0.5)\n                white_light_readback = await _imou_get_capability_switch(\n                    client,\n                    device_id,\n                    channel_id,\n                    "linkageWhiteLight",\n                )\n                siren_readback, siren_scope = await _imou_read_linkage_siren(\n                    client,\n                    device_id,\n                    channel_id,\n                )\n\n            if white_light_readback == desired and siren_readback == desired:\n                deterrence_successes += 1\n            else:\n                deterrence_errors.append(\n                    f"{entry.entry_id}:readback_mismatch"\n                )\n        except Exception as err:\n            deterrence_errors.append(\n                f"{entry.entry_id}:{type(err).__name__}:{err}"\n            )\n            _LOGGER.exception(\n                "Failed to sync Imou alarm-linked deterrence for entry %s",\n                entry.entry_id,\n            )\n\n    if callback_successes:\n        runtime["imou_last_desired"] = desired\n        _set_diag(\n            hass,\n            IMOU_DIAG,\n            "on" if desired else "off",\n            desired=desired,\n            security_state=security_state,\n            reason=policy_reason,\n            provider="Imou",\n            sync_reason=sync_reason,\n            base_push="1" if desired else "2",\n            attempted_entries=attempted,\n            synced_entries=callback_successes,\n            errors=callback_errors,\n            wrote_api=callback_wrote,\n            confirmation=(\n                "Open Platform callback API write"\n                if callback_wrote\n                else "last successful API write"\n            ),\n        )\n    else:\n        _set_diag(\n            hass,\n            IMOU_DIAG,\n            "unavailable",\n            desired=desired,\n            security_state=security_state,\n            reason=policy_reason,\n            provider="Imou",\n            sync_reason=sync_reason,\n            attempted_entries=attempted,\n            errors=callback_errors or ["target Imou entry not ready"],\n        )\n\n    deterrence_ok = (\n        deterrence_successes > 0\n        and white_light_readback == desired\n        and siren_readback == desired\n    )\n    _set_deterrence_diag(\n        hass,\n        ("on" if desired else "off") if deterrence_ok else "unavailable",\n        desired=desired,\n        security_state=security_state,\n        reason=policy_reason,\n        sync_reason=sync_reason,\n        device_id=device_id,\n        channel_id=channel_id,\n        linkage_white_light=white_light_readback,\n        linkage_siren=siren_readback,\n        siren_scope=("device" if siren_scope is None else f"channel:{siren_scope}"),\n        attempted_entries=attempted,\n        synced_entries=deterrence_successes,\n        wrote_api=deterrence_wrote,\n        errors=deterrence_errors,\n        confirmation=(\n            "Open Platform capability readback"\n            if deterrence_ok\n            else "readback not confirmed"\n        ),\n    )\n'
text = text[:start] + new_sync + text[end:]

old = '    @callback\n    def _periodic(_now: Any) -> None:\n        # EZVIZ has a cloud readback and therefore repairs vendor-side drift.\n        # Imou avoids periodic API writes unless its desired policy changed.\n        hass.async_create_task(_sync_all("periodic_drift_check"))\n'
new = '    @callback\n    def _periodic(_now: Any) -> None:\n        # EZVIZ app push and Imou alarm-linked deterrence have cloud readbacks.\n        # Imou callback/basePush is re-written only when its desired policy changes.\n        hass.async_create_task(_sync_all("periodic_drift_check"))\n'
assert text.count(old) == 1
text = text.replace(old, new, 1)

old = '            ez = hass.states.get(EZVIZ_DIAG)\n            im = hass.states.get(IMOU_DIAG)\n            if (\n                ez is None\n                or im is None\n                or ez.state == "unavailable"\n                or im.state == "unavailable"\n            ):\n'
new = '            ez = hass.states.get(EZVIZ_DIAG)\n            im = hass.states.get(IMOU_DIAG)\n            deterrence = hass.states.get(IMOU_DETERRENCE_DIAG)\n            if (\n                ez is None\n                or im is None\n                or deterrence is None\n                or ez.state == "unavailable"\n                or im.state == "unavailable"\n                or deterrence.state == "unavailable"\n            ):\n'
assert text.count(old) == 1
text = text.replace(old, new, 1)

ast.parse(text)
assert text != original

stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
backup = Path(str(PATH) + f".bak-deterrence-{stamp}")
